mapper.insert:
INSERT INTO search_log (
    user_id, session_id, query, normalized_query, expanded_query,
    result_count, response_ms, locale, domain_filter, ip_hash
) VALUES (
    #{userId}, #{sessionId}, #{query}, #{normalizedQuery}, #{expandedQuery},
    #{resultCount}, #{responseMs}, #{locale}, #{domainFilter}, #{ipHash}
)

mapper.select:
SELECT locale AS "locale", normalized_query AS "normalizedQuery", COUNT(*) AS "searchCount" FROM search_log WHERE created_at >= #{from}::date AND created_at < (#{to}::date + INTERVAL '1 day')
AND locale = #{locale}
GROUP BY locale, normalized_query ORDER BY locale, "searchCount" DESC
